-- ==============================================
-- ARTICLE: Cazadores de Serpientes (cazadores-de-serpientes)
-- ==============================================
DO $$
DECLARE
  v_admin_id UUID;
  v_articulo_id UUID;
BEGIN
  SELECT id INTO v_admin_id FROM perfiles WHERE rol_id = 1 LIMIT 1;
  IF v_admin_id IS NULL THEN
    SELECT id INTO v_admin_id FROM perfiles LIMIT 1;
  END IF;

  DELETE FROM articulos WHERE slug = 'cazadores-de-serpientes';

  v_articulo_id := uuid_generate_v4();

  INSERT INTO articulos (
    id,
    autor_id,
    categoria_id,
    titulo,
    slug,
    contenido,
    extracto,
    imagen_destacada,
    estado,
    etiquetas,
    metadata
  ) VALUES (
    v_articulo_id,
    v_admin_id,
    NULL,
    'Cazadores de Serpientes',
    'cazadores-de-serpientes',
    $html$<h2>📜 Descripción de Cazadores de Serpientes</h2><p><strong>Cazadores de Serpientes</strong> es un apasionante y dinámico juego scout de agilidad, atención alerta y velocidad de reacción. Los participantes orbitan en un círculo alrededor de un conjunto de cuerdas dispersas en el terreno, compitiendo velozmente por capturar una al escuchar la señal auditiva del dirigente.</p><hr><h3>🎲 ¿Cómo se juega Cazadores de Serpientes?</h3><ol><li><strong>Preparación:</strong> Se colocan en el centro del terreno tantas cuerdas (llamadas "serpientes") como participantes haya en el juego, menos una. Los jugadores forman un gran círculo rodeando el área a 5 metros de distancia.</li><li><strong>Inicio del Desplazamiento:</strong> A la señal del dirigente (un silbatazo o aplauso), los jóvenes comienzan a correr o trotar en círculo alrededor del área delimitada sin acercarse prematuramente a las cuerdas.</li><li><strong>La Captura:</strong> Cuando el dirigente grita <em>"¡Serpiente!"</em> o hace sonar dos pitazos cortos, todos los participantes deben romper el círculo y correr al centro para coger una cuerda. El jugador que no alcance a capturar una "serpiente" queda temporalmente eliminado de la ronda.</li><li><strong>Prueba de Velocidad (Empates):</strong> Si dos jugadores agarran los extremos de la misma cuerda simultáneamente, el dirigente retira esa cuerda y realiza un duelo rápido colocando una cuerda neutral a mitad de camino entre ambos.</li><li><strong>Ronda Final:</strong> Se retira una cuerda tras cada ronda y se repite la dinámica hasta coronar al gran cazador de serpientes de la unidad.</li></ol>$html$,
    'Un apasionante juego scout de agilidad y velocidad de reacción donde los competidores corren por capturar cuerdas dispersas en el terreno.',
    '/uploads/actividad_cazadoresSerpientes.webp',
    'publicado',
    ARRAY['juego-fisico', 'agilidad', 'cuerdas', 'velocidad', 'exterior'],
    $json${"areas": ["corporalidad", "carácter", "sociabilidad"], "lugares": ["Exterior", "campo delimitado"], "cantidad": "04 participantes", "duracion": "15 minutos", "unidades": ["manada", "compañía", "tropa", "avanzada"], "descargas": [], "objetivos": ["Refuerzo de habilidades físicas", "Estimular la agilidad mental", "Fomentar un entorno de confianza", "Favorecer el conocimiento entre los pares"], "materiales": ["Cuerdas"], "variaciones": "Serpientes Venenosas (Variante con Nudos): Algunas cuerdas tienen nudos en las puntas (\"serpientes venenosas\"). Quien atrapa una cuerda con nudo debe dar 3 giros sobre su eje antes de poder cantar victoria.\n\nCaza Nocturna con Linternas: Las cuerdas se colocan en penumbra y los participantes deben ubicarlas iluminando brevemente con sus linternas.\n\nSerpientes en Parejas: Los integrantes corren tomados del brazo en duplas de patrulla, exigiendo coordinación física conjunta para llegar primeros a la cuerda.", "recomendaciones": "Seguridad y Terreno Despejado: Asegurarse de utilizar cuerdas suaves sin puntas metálicas ni nudos duros que puedan golpear la cara. Jugar en césped libre de ramas o piedras.\n\nControl del Juego Rudo: Advertir firmemente que no se permiten empujones ni jalones de manos entre compañeros. La captura se valida según quien ponga primero su mano firmemente sobre la cuerda.\n\nInclusividad y Animación: Animar con entusiasmo a los participantes eliminados para que asuman el rol de jueces de línea observando los empates.", "justificacion_areas": "Cazadores de Serpientes estimula la corporalidad al ejercitar reflejos de reacción rápida, aceleración y agilidad física. Fortalece el carácter al promover el respeto riguroso por las reglas de eliminación y la aceptación alegre del resultado, y desarrolla la sociabilidad al afianzar la empatía y la convivencia limpia en el grupo.", "objetivos_educativos": [{"id": "5cbe35dc-d15b-4070-9a36-5b0e652c7946", "area": "Sociabilidad", "texto": "Respeto las opiniones de los demás.", "unidad": "Manada", "como_se_cumple": "Respetando los derechos de todos los lobatos a participar en igualdad de condiciones."}, {"id": "d5b111f1-5f6f-4716-8a02-e1826d653c59", "area": "Corporalidad", "texto": "Participo en los juegos, excursiones y campamentos que organiza mi patrulla.", "unidad": "Compañía", "como_se_cumple": "Demostrando rapidez y flexibilidad en el terreno delimitado."}, {"id": "b12da732-d736-480c-82b8-95b312316390", "area": "Corporalidad", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "unidad": "Compañía", "como_se_cumple": "Coordinando impulsos velozmente durante los duelos de desempate."}, {"id": "fce82191-77ea-444b-89d9-e33b62a323a5", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeras, cualquiera sea su manera de ser.", "unidad": "Compañía", "como_se_cumple": "Fomentando el fair play y la consideración por las compañeras."}, {"id": "117bbf3f-7e3d-4c61-b305-821609bf2e5a", "area": "Carácter", "texto": "Contribuyo al ambiente de alegría de mi Compañía.", "unidad": "Compañía", "como_se_cumple": "Disfrutando momentos de distensión y camaradería con la patrulla."}, {"id": "25b24d3a-9d47-44af-b460-680508e644f3", "area": "Carácter", "texto": "Soy alegre.", "unidad": "Compañía", "como_se_cumple": "Afrontando las pruebas rápidas con optimismo y juego limpio."}, {"id": "944660c8-0093-4181-ba2c-5f95cc74ba47", "area": "Sociabilidad", "texto": "No me gusta cuando no se respetan los derechos humanos y lo digo.", "unidad": "Compañía", "como_se_cumple": "Favoreciendo un ambiente seguro donde se respete la integridad de todos."}, {"id": "58b4936a-816e-4d17-8d0a-c92d0606009d", "area": "Corporalidad", "texto": "Participo en los juegos, excursiones y campamentos que organiza mi patrulla.", "unidad": "Tropa", "como_se_cumple": "Ejercitando mi agilidad corporal y reflejos rápidos en la carrera por las cuerdas."}, {"id": "6768d60a-187e-4bbf-97b9-cdc25a316030", "area": "Corporalidad", "texto": "Ayudo a preparar los juegos, excursiones y campamentos de mi patrulla y mi Tropa.", "unidad": "Tropa", "como_se_cumple": "Esforzándome por mejorar mi rendimiento físico manteniendo el juego limpio."}, {"id": "4d66ed86-48ec-4801-bd0a-e5c8d023c8cd", "area": "Carácter", "texto": "Enfrento y resuelvo mis dificultades con alegría.", "unidad": "Tropa", "como_se_cumple": "Aceptando los resultados del juego con caballerosidad y sentido del humor."}, {"id": "9a38e454-f93a-40a5-9f68-e500ba7e0655", "area": "Carácter", "texto": "Comparto mi alegría con mis amigos, amigos y familia.", "unidad": "Tropa", "como_se_cumple": "Animando a los compañeros eliminados a continuar apoyando desde el exterior."}, {"id": "a3d7abdf-ca3b-42b8-92b5-403958fb537c", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeros, cualquiera sea su manera de ser.", "unidad": "Tropa", "como_se_cumple": "Respetando las decisiones de los árbitros y dirigentes durante los desempates."}, {"id": "0d3af46a-d64c-4e59-a765-1f72dc41ba76", "area": "Sociabilidad", "texto": "Ayudo a mi patrulla en los compromisos que tomamos.", "unidad": "Tropa", "como_se_cumple": "Promoviendo el respeto por el esfuerzo de cada integrante de la unidad."}, {"id": "7200435f-b020-46fc-b323-8249048b1d18", "area": "Corporalidad", "texto": "Participo en la organización de juegos y actividades recreativas para los demás.", "unidad": "Avanzada", "como_se_cumple": "Liderando pruebas de agilidad física recreativa con entusiasmo en la comunidad."}, {"id": "4b2e406f-2d78-4039-9ce2-4ccb743eb553", "area": "Carácter", "texto": "Soy capaz de reírme de mis propios absurdos.", "unidad": "Avanzada", "como_se_cumple": "Propiciando un clima grato y festivo durante las dinámicas grupales."}, {"id": "5abfbe81-75e4-4444-b52d-38e59e8b6ec7", "area": "Sociabilidad", "texto": "Estoy siempre disponible para ayudar a los demás, incluso cuando se trata de tareas pesadas o poco agradables.", "unidad": "Avanzada", "como_se_cumple": "Asumiendo actitudes solidarias y colaborativas durante las actividades de campamento."}, {"id": "4bf1e3dd-7f21-4c24-962d-9d6d64e32f25", "area": "Corporalidad", "texto": "Me gusta hacer actividades al aire libre.", "unidad": "Manada", "como_se_cumple": "Desplegando velocidad de reacción al correr hacia la serpiente al escuchar la señal del dirigente."}, {"id": "5d2d48ed-c461-4a8e-9048-cceecd3de2e2", "area": "Corporalidad", "texto": "Me gusta jugar con otros niños y niñas y respeto las reglas de los juegos.", "unidad": "Manada", "como_se_cumple": "Participando con destreza física respetando las reglas de eliminación del juego."}, {"id": "8c1cbf88-6e1d-496b-b789-9e0b767c8814", "area": "Carácter", "texto": "Casi siempre estoy alegre.", "unidad": "Manada", "como_se_cumple": "Tomando con alegría y risas la eliminación temporal del juego."}, {"id": "d408da3c-207d-4442-a891-8f50efbeecb1", "area": "Carácter", "texto": "Enfrento las dificultades con buen ánimo.", "unidad": "Manada", "como_se_cumple": "Manteniendo un espíritu alegre y deportivo durante las distintas rondas."}, {"id": "cfa10133-c25c-4deb-aebe-a00f8fe3f7ef", "area": "Sociabilidad", "texto": "Comparto lo que tengo con mis compañeros y compañeras.", "unidad": "Manada", "como_se_cumple": "Compartiendo el espacio de carrera de forma respetuosa sin empujar a mis compañeros."}]}$json$::jsonb
  );

